('lib/content/gpx_scolarite/pv_apj20/introduction/procedure_page.dart','f00030','V — Fin d’enquête & transmission',30,'_Paragraph','Des instructions émanant de chaque direction active précisent les modalités d’emploi des gardiens A.P.J. 20.','Des instructions émanant de chaque direction active précisent les modalités d’emploi des gardiens A.P.J. 20.','{}'::jsonb,true),
