('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00005','I — Élément légal',5,'TextSpan','Article 429 du Code de procédure pénale','Article 429 du Code de procédure pénale','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00006','I — Élément légal',6,'TextSpan',' : encadre la valeur probante du procès-verbal, qui n’est reconnue que s’il est régulier en la forme, établi par un auteur compétent, dans l’exercice de ses fonctions, et sur une matière de sa compétence (faits vus, entendus ou constatés personnellement).',' : encadre la valeur probante du procès-verbal, qui n’est reconnue que s’il est régulier en la forme, établi par un auteur compétent, dans l’exercice de ses fonctions, et sur une matière de sa compétence (faits vus, entendus ou constatés personnellement).','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00007','Définition',7,'title','Définition','Définition','{}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00008','Définition',8,'_Paragraph','Le procès-verbal est un acte écrit, rédigé et signé par un magistrat, un officier ou un agent de police judiciaire, agissant conformément aux règles de leur compétence, et dans le cadre d’une mission de police judiciaire.','Le procès-verbal est un acte écrit, rédigé et signé par un magistrat, un officier ou un agent de police judiciaire, agissant conformément aux règles de leur compétence, et dans le cadre d’une mission de police judiciaire.','{}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00009','II — La valeur des procès-verbaux',9,'title','II — La valeur des procès-verbaux','II — La valeur des procès-verbaux','{}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00010','II — La valeur des procès-verbaux',10,'TextSpan','Sauf disposition contraire, ','Sauf disposition contraire, ','{"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00011','II — La valeur des procès-verbaux',11,'TextSpan','les procès-verbaux et rapports constatant les délits','les procès-verbaux et rapports constatant les délits','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00012','II — La valeur des procès-verbaux',12,'TextSpan',' ne valent qu’à titre de simples renseignements — ',' ne valent qu’à titre de simples renseignements — ','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
