('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00014','II — La valeur des procès-verbaux',14,'_SubTitle','A) PV valant simples renseignements','A) PV valant simples renseignements','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00015','II — La valeur des procès-verbaux',15,'TextSpan','Article 430 du Code de procédure pénale','Article 430 du Code de procédure pénale','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00016','II — La valeur des procès-verbaux',16,'TextSpan',' : en enquête de flagrance (sauf loi spéciale), en enquête préliminaire ou en exécution d’une commission rogatoire, les PV n’apportent pas de valeur probante aux faits relatés : ils jouent un rôle d’information.',' : en enquête de flagrance (sauf loi spéciale), en enquête préliminaire ou en exécution d’une commission rogatoire, les PV n’apportent pas de valeur probante aux faits relatés : ils jouent un rôle d’information.','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00017','II — La valeur des procès-verbaux',17,'string','Conséquence : le juge apprécie librement, le PV informe mais ne « prouve » pas à lui seul.','Conséquence : le juge apprécie librement, le PV informe mais ne « prouve » pas à lui seul.','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00018','II — La valeur des procès-verbaux',18,'_SubTitle','B) PV valant jusqu’à preuve contraire','B) PV valant jusqu’à preuve contraire','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00019','II — La valeur des procès-verbaux',19,'TextSpan','Article 431 du Code de procédure pénale','Article 431 du Code de procédure pénale','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00020','II — La valeur des procès-verbaux',20,'TextSpan',' : une disposition expresse de la loi peut conférer au PV une force probante renforcée. La preuve contraire ne peut alors être apportée que par écrit ou par témoins (ex. : dispositions spéciales, comme certains domaines du droit du travail).',' : une disposition expresse de la loi peut conférer au PV une force probante renforcée. La preuve contraire ne peut alors être apportée que par écrit ou par témoins (ex. : dispositions spéciales, comme certains domaines du droit du travail).','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00021','II — La valeur des procès-verbaux',21,'string','Règle d’or : le rédacteur relate uniquement ce qu’il a personnellement vu, entendu ou constaté.','Règle d’or : le rédacteur relate uniquement ce qu’il a personnellement vu, entendu ou constaté.','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00022','II — La valeur des procès-verbaux',22,'_SubTitle','C) PV valant jusqu’à inscription de faux','C) PV valant jusqu’à inscription de faux','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00023','II — La valeur des procès-verbaux',23,'TextSpan','Article 433 du Code de procédure pénale','Article 433 du Code de procédure pénale','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00024','II — La valeur des procès-verbaux',24,'TextSpan',' : certaines matières, prévues par des lois spéciales, donnent lieu à des PV faisant foi jusqu’à inscription de faux (souvent rédigés par des agents spécialisés : douanes, ONF, etc.).',' : certaines matières, prévues par des lois spéciales, donnent lieu à des PV faisant foi jusqu’à inscription de faux (souvent rédigés par des agents spécialisés : douanes, ONF, etc.).','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00025','II — La valeur des procès-verbaux',25,'title','Autorité','Autorité','{}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00026','II — La valeur des procès-verbaux',26,'TextSpan','L’autorité de ces PV est très forte : le juge est lié tant que les conditions légales sont réunies (infraction constituée, compétence de l’agent, absence de prescription/amnestie, absence de vice de forme).','L’autorité de ces PV est très forte : le juge est lié tant que les conditions légales sont réunies (infraction constituée, compétence de l’agent, absence de prescription/amnestie, absence de vice de forme).','{}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00027','III — Les principes de rédaction',27,'title','III — Les principes de rédaction','III — Les principes de rédaction','{}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00028','III — Les principes de rédaction',28,'_SubTitle','A) Principes','A) Principes','{}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00029','III — Les principes de rédaction',29,'_SubTitle','Simultanéité : le PV doit être rédigé « sur-le-champ » ou dès que possible (perquisition, constatations, audition…).','Simultanéité : le PV doit être rédigé « sur-le-champ » ou dès que possible (perquisition, constatations, audition…).','{}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00030','III — Les principes de rédaction',30,'string','Spécificité : traditionnellement, un PV par opération de police judiciaire.','Spécificité : traditionnellement, un PV par opération de police judiciaire.','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00031','III — Les principes de rédaction',31,'TextSpan','Article D.11 du Code de procédure pénale','Article D.11 du Code de procédure pénale','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00032','III — Les principes de rédaction',32,'TextSpan',' : autorise, en flagrance ou en préliminaire, à relater dans un seul PV les opérations effectuées au cours d’une même enquête (procédure simplifiée : vol à l’étalage, vente à la sauvette, usage de stupéfiants, etc.).',' : autorise, en flagrance ou en préliminaire, à relater dans un seul PV les opérations effectuées au cours d’une même enquête (procédure simplifiée : vol à l’étalage, vente à la sauvette, usage de stupéfiants, etc.).','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00033','III — Les principes de rédaction',33,'string','Unicité du rédacteur : l’en-tête comporte l’identité du rédacteur (ou R.I.O. selon conditions), grade, service et qualité CPP.','Unicité du rédacteur : l’en-tête comporte l’identité du rédacteur (ou R.I.O. selon conditions), grade, service et qualité CPP.','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00034','III — Les principes de rédaction',34,'TextSpan','Références : ','Références : ','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00035','III — Les principes de rédaction',35,'TextSpan','articles D.9 et D.10 du Code de procédure pénale','articles D.9 et D.10 du Code de procédure pénale','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00036','III — Les principes de rédaction',36,'TextSpan','Copie : une copie du PV doit toujours être établie et jointe à l’original destiné au magistrat.','Copie : une copie du PV doit toujours être établie et jointe à l’original destiné au magistrat.','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00037','III — Les principes de rédaction',37,'TextSpan','Article 19 du Code de procédure pénale','Article 19 du Code de procédure pénale','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00038','III — Les principes de rédaction',38,'TextSpan',' : impose la copie jointe à l’original.',' : impose la copie jointe à l’original.','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00039','III — Les principes de rédaction',39,'_SubTitle','B) Protection du rédacteur & assistants','B) Protection du rédacteur & assistants','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00040','III — Les principes de rédaction',40,'TextSpan','Article 15-3 du Code de procédure pénale','Article 15-3 du Code de procédure pénale','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00041','III — Les principes de rédaction',41,'TextSpan',' : le rédacteur d’un PV de plainte (OPJ/APJ) peut s’identifier par son numéro d’immatriculation administrative (R.I.O.) sans autorisation préalable.',' : le rédacteur d’un PV de plainte (OPJ/APJ) peut s’identifier par son numéro d’immatriculation administrative (R.I.O.) sans autorisation préalable.','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00042','III — Les principes de rédaction',42,'TextSpan','Article 15-4 du Code de procédure pénale','Article 15-4 du Code de procédure pénale','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00043','III — Les principes de rédaction',43,'TextSpan',' : tout agent de la police nationale peut s’identifier par son R.I.O. dans les actes qu’il rédige ou dans lesquels il est cité comme assistant, sans faire apparaître nom et prénom (sous réserve des conditions légales et, dans certains cas, d’une autorisation).',' : tout agent de la police nationale peut s’identifier par son R.I.O. dans les actes qu’il rédige ou dans lesquels il est cité comme assistant, sans faire apparaître nom et prénom (sous réserve des conditions légales et, dans certains cas, d’une autorisation).','{"color_hints":["_lawRed"],"font_weight_hints":["FontWeight.w900"]}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00044','III — Les principes de rédaction',44,'TextSpan','Cette protection vise les situations où la révélation de l’identité est susceptible de mettre en danger la vie ou l’intégrité physique de l’agent ou de ses proches, compte tenu des conditions d’exercice ou de la nature des faits constatés.','Cette protection vise les situations où la révélation de l’identité est susceptible de mettre en danger la vie ou l’intégrité physique de l’agent ou de ses proches, compte tenu des conditions d’exercice ou de la nature des faits constatés.','{}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00045','IV — Structure & techniques de rédaction',45,'title','IV — Structure & techniques de rédaction','IV — Structure & techniques de rédaction','{}'::jsonb,true),
('lib/content/gpx_scolarite/pv_apj20/introduction/proces_verbaux_page.dart','f00046','IV — Structure & techniques de rédaction',46,'_Paragraph','Chaque feuillet du procès-verbal doit être écrit et signé par son rédacteur. Seule la langue française doit être utilisée. Le procès-verbal peut être manuscrit ou dactylographié.','Chaque feuillet du procès-verbal doit être écrit et signé par son rédacteur. Seule la langue française doit être utilisée. Le procès-verbal peut être manuscrit ou dactylographié.','{}'::jsonb,true),
